+            switch (op.b()) {
+                case ValueTypes.COLOR -> {
+                    if ("color.primary".equals(frame.stringAt(op.a()))) {
+                        sawColor = true;
+                        assertEquals(0xFF2563EB, op.c());
+                    } else {
+                        sawDark = true;
