+                        assertEquals(0xFF60A5FA, op.c());
+                    }
+                }
+                case ValueTypes.F32 -> {
+                    sawF32 = true;
+                    assertEquals("space.base", frame.stringAt(op.a()));
+                    assertEquals(4.0f, Float.intBitsToFloat(op.c()));
+                }
+                case ValueTypes.STRING -> {
+                    sawString = true;
+                    assertEquals("font.body.family", frame.stringAt(op.a()));
+                    assertEquals("Inter", frame.stringAt(op.c()));
+                }
+                default -> { }
+            }
+        }
+        assertTrue(sawColor, "base color override emitted");
+        assertTrue(sawDark, "dark color override emitted");
+        assertTrue(sawF32, "f32 override emitted");
+        assertTrue(sawString, "STRING override emitted");
+
+        // Overrides ride the network batch too.
+        Frame decoded = FrameCodec.decodeFrame(FrameCodec.encodeFrame(frame));
+        assertEquals(frame.opcodes(), decoded.opcodes());
+    }
