     event_slots: &'a mut [u8],
     arena: &'a mut [u8],
     /// Host → guest event arena (host-owned bump; the guest resolves `TEXT_CHANGED`
     /// text here over the shared ring).
     event_arena: &'a mut [u8],
     /// Write cursor captured at `begin_frame`.
     frame_start: u32,
