 ///
 /// There is deliberately **no** `.color()` / `.foregroundColor()` modifier.
 #[derive(Debug, Clone, Copy, PartialEq)]
 pub enum Color {
     /// A literal sRGB color (`0xAARRGGBB`).
     Literal(u32),
     /// A reference to a design token path (e.g. `color.primary`, `dark.color.primary`).
     Token(&'static str),
 }

