```java
package com.pathland.view;

import java.util.ArrayList;
import java.util.List;

public final class Theme {
    private final List<Override> overrides = new ArrayList<>();
    private record Override(String path, int valueType, Object value) {}

    public Theme color(String path, int argb) { return push(path, ValueTypes.COLOR, Color.of(argb)); }
    public Theme darkColor(String path, int argb) { return push(dark(path), ValueTypes.COLOR, Color.of(argb)); }
    public Theme f32(String path, float value) { return push(path, ValueTypes.F32, value); }
    public Theme darkF32(String path, float value) { return push(dark(path), ValueTypes.F32, value); }
    public Theme u32(String path, int value) { return push(path, ValueTypes.U32, value); }
    public Theme u8(String path, int value) { return push(path, ValueTypes.U8, value); }
    public Theme string(String path, String value) { return push(path, ValueTypes.STRING, value); }
    public Theme darkString(String path, String value) { return push(dark(path), ValueTypes.STRING, value); }

    private static String dark(String path) {
        return path.startsWith("dark.") ? path : "dark." + path;
    }

    private Theme push(String path, int valueType, Object value) {
        overrides.add(new Override(path, valueType, value));
        return this;
    }

    /** Emit all overrides as one frame of STYLE::SET_DESIGN_TOKEN opcodes. */
    public void emit(OpcodeSink sink) {
        sink.beginFrame();
        for (Override o : overrides) {
            sink.setDesignToken(o.path(), o.valueType(), o.value());
        }
        sink.endFrame();
    }
}
```

`Color.of(argb)` exists. Good.

Now `OpcodeSink.setDesignToken`. Default method? Since only two impls exist, add abstract and implement in both. But tests might define anonymous OpcodeSink... grep found only FrameOpcodeSink and RingOpcodeSink implement it. But to be safe against future breakage and reduce churn, I'll make it a `default` method that throws UnsupportedOperationException. Actually a default that emits nothing is dangerous. Let me just add it abstract; both impls updated. Tests don't implement OpcodeSink directly.

