  if (typeof value === "string") {
    return `'${value.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
  }
  const v = tokenCssValue(valueType, value);
  return isLengthToken(path) && valueType === VAL_F32 ? v + "px" : v;
}

