//! GTK-native design-token defaults.
use std::collections::BTreeMap;
use pathland_core::tokens::TokenValue;
use crate::host::concrete_default_tables;

/// Tier-1 default tables: concrete platform-appropriate fallbacks, with the
/// tokens the current GTK theme can resolve (`StyleContext::lookup_color` of
/// `@theme_*` names) replaced by native colors for the **currently active**
/// scheme. Headless (no display) → pure concrete fallback.
pub fn gtk_defaults() -> (BTreeMap<String, TokenValue>, BTreeMap<String, TokenValue>) {
    let (mut base, mut dark) = concrete_default_tables();
    let ctx = gtk::StyleContext::new();
    for (name, path) in NAMED_COLORS {
