    ... create node with COLOR token ref ...
    // override
    let mut guest = Guest::new(&mut mem, &layout);
    guest.begin_frame();
    guest.set_design_token("color.primary", value_type::COLOR, 0xFF_123456).unwrap();
    guest.end_frame();
    let frame = host.frames()[0]; // new frame
    tree.apply_frame(&frame);
    assert properties[COLOR] == 0xFF123456
    // dark scheme
    tree.set_scheme(Scheme::Dark);
    assert properties[COLOR] == dark override? No override for dark. dark defaults: color.primary dark = 0xFF60A5FA. But we have a base override 0xFF123456 which falls through when dark layer empty. So Dark → 0xFF123456 (base override). Good — matches conformance.
    // Now add dark override:
    guest.set_design_token("dark.color.primary", ...0xFFABCDEF)
    apply → Dark resolves 0xFFABCDEF.
