#[test]
fn design_token_override_and_scheme_change_re_resolve() {
    let layout = MemoryLayout::default();
    let mut mem = vec![0u8; layout.total_bytes()];
    init_memory(&mut mem, &layout);

    let mut root = text("x").foreground_style(pathland_view::Color::token("color.primary")).build();
    assign_ids(&mut root, &mut 1);
    let mut engine = Engine::new();
    {
        let mut guest = Guest::new(&mut mem, &layout);
        guest.begin_frame();
        engine.emit(&root, &mut guest).unwrap();
        guest.end_frame();
    }
    let mut host = Host::new(&mut mem, &layout);
    let mut tree = RenderTree::default();
    tree.apply_frame(&host.frames()[0]);

    // Base override wins (light).
    {
        let mut guest = Guest::new(&mut mem, &layout);
        guest.begin_frame();
        guest.set_design_token("color.primary", value_type::COLOR, 0xFF_123456).unwrap();
        guest.end_frame();
        let mut host = Host::new(&mut mem, &layout);
        tree.apply_frame(&host.frames()[0]);
    }
    assert_eq!(tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(), Some(0xFF_123456));

    // Dark scheme: base override falls through when the dark layer is empty.
    tree.set_scheme(Scheme::Dark);
    assert_eq!(tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(), Some(0xFF_123456));

    // A dark.* override wins under the dark scheme.
