        let mut guest = Guest::new(&mut mem, &layout);
        guest.begin_frame();
        guest.set_design_token("dark.color.primary", value_type::COLOR, 0xFF_ABCDEF).unwrap();
        guest.end_frame();
        let mut host = Host::new(&mut mem, &layout);
        tree.apply_frame(&host.frames()[0]);
    }
    assert_eq!(tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(), Some(0xFF_ABCDEF));

    // Back to light: the base override wins again.
    tree.set_scheme(Scheme::Light);
    assert_eq!(tree.node(1).unwrap().properties.get(&property_id::COLOR).copied(), Some(0xFF_123456));
}

