                         if let Some(s) = self.snapshot_mut(node) {
                             s.text = new_text;
                         }
                     }
                 }
                 Dep::Property { node, prop } => {
                     let new_value = self
                         .store
                         .get(id)
                         .and_then(SignalValue::to_property_u32);
                     let prev_value = self.snapshot_property(node, prop);
                     if new_value != prev_value {
                         if let Some(v) = new_value {
