 /// Stack main-axis gap.
 #[derive(Debug, Clone, Copy, PartialEq)]
 pub struct Spacing(pub f32);

 /// Uniform padding (a styling modifier, applied to any view).
 #[derive(Debug, Clone, Copy, PartialEq)]
